/**
 * GENERATED brand icons (Dr. Pinguin graduation-cap penguin), served by server/middleware/brand-icons.ts.
 * Source: owner-supplied penguin artwork, caption + watermark cropped out. Small sizes (favicon 16/32/48)
 * use a head crop for legibility; 180/192/512 show head + body. Stored as base64 because the repo is
 * updated through a text-only API; decoded once per isolate.
 */
export type BrandIcon = { type: string; b64: string };

export const BRAND_ICONS: Record<string, BrandIcon> = {
  "/favicon.ico": { type: "image/x-icon", b64: "" },
  "/favicon-32.png": { type: "image/png", b64: "" },
  "/apple-touch-icon.png": { type: "image/png", b64: "" },
  "/icon-192.png": { type: "image/png", b64: "" },
  "/icon-512.png": { type: "image/png", b64: "" },
  "/icon-512-maskable.png": { type: "image/png", b64: "" },
};
